306	pub fn compact(key: &str, doc: &Doc, updated_at: u64) -> Result<TileRecord, String> {
307	    let coord = parse_tile_key(key)?;
308	    let txn = doc.transact();
309	    let doc_state = txn.encode_state_as_update_v1(&StateVector::default());
310	    let mut objects = Vec::new();
311	    if let Some(map) = txn.get_map(OBJECTS) {
312	        for (object_id, value) in map.iter(&txn) {
313	            let Out::Any(Any::Buffer(bytes)) = value else {
314	                return Err(format!("object {object_id:?} must be a CBOR byte string"));
315	            };
316	            let object = crate::object::decode(&bytes)?;
317	            objects.push((object_id.to_owned(), object.bbox().clone()));
318	        }
319	    }
320	    objects.sort_by(|a, b| a.0.cmp(&b.0));
321	    Ok(TileRecord {
322	        coord,
323	        doc_state,
324	        updated_at,
325	        objects,
326	    })
327	}
