329	fn stamp_user(update: &mut AwarenessUpdate, user: &str) -> Result<(), String> {
330	    for entry in update.clients.values_mut() {
331	        let mut state: serde_json::Value = serde_json::from_str(&entry.json)
332	            .map_err(|e| format!("invalid awareness state: {e}"))?;
333	        let Some(fields) = state.as_object_mut() else {
334	            continue;
335	        };
336	        let identity = fields
337	            .entry("user")
338	            .or_insert_with(|| serde_json::Value::Object(Default::default()));
339	        if !identity.is_object() {
340	            *identity = serde_json::Value::Object(Default::default());
341	        }
342	        identity["name"] = user.into();
343	        entry.json = state.to_string().into();
344	    }
345	    Ok(())
346	}
