363	fn apply(doc: &Doc, update: &[u8]) -> Result<Applied, String> {
364	    let trial = Doc::new();
365	    let current = doc
366	        .transact()
367	        .encode_state_as_update_v1(&StateVector::default());
368	    {
369	        let mut txn = trial.transact_mut();
370	        txn.apply_update(decode_update(&current)?)
371	            .map_err(|e| e.to_string())?;
372	        txn.apply_update(decode_update(update)?)
373	            .map_err(|e| e.to_string())?;
374	    }
375	    let txn = trial.transact();
376	    if txn.store().pending_update().is_some() || txn.store().pending_ds().is_some() {
377	        return Ok(Applied::MissingDependencies);
378	    }
379	    if let Some((name, _)) = txn.root_refs().find(|(name, _)| *name != OBJECTS) {
380	        return Err(format!(
381	            "unknown root type {name:?}; only {OBJECTS:?} is allowed"
382	        ));
383	    }
384	    if let Some(objects) = txn.get_map(OBJECTS) {
385	        let before_txn = doc.transact();
386	        let before = before_txn.get_map(OBJECTS);
387	        for (object_id, value) in objects.iter(&txn) {
388	            let unchanged = before
389	                .as_ref()
390	                .and_then(|map| map.get(&before_txn, object_id))
391	                .is_some_and(|old| old == value);
392	            if !unchanged {
393	                validate_entry(object_id, &value)?;
394	            }
395	        }
396	    }
397	    let update = decode_update(update)?;
398	    let changed = !update.is_empty();
399	    doc.transact_mut()
400	        .apply_update(update)
401	        .map_err(|e| e.to_string())?;
402	    Ok(Applied::Integrated { changed })
403	}
404	
405	fn validate_entry(object_id: &str, value: &Out) -> Result<(), String> {
406	    let Out::Any(Any::Buffer(bytes)) = value else {
407	        return Err(format!("object {object_id:?} must be a CBOR byte string"));
408	    };
409	    let object = crate::object::decode(bytes).map_err(|e| format!("object {object_id:?}: {e}"))?;
410	    if object.object_id() != object_id {
411	        return Err(format!(
412	            "object stored under {object_id:?} has objectId {:?}",
413	            object.object_id()
414	        ));
415	    }
416	    Ok(())
417	}
