638	    impl Client {
639	        fn new() -> Self {
640	            Client {
641	                doc: Doc::new(),
642	                session: Session::default(),
643	                inbox: Vec::new(),
644	            }
645	        }
646	
647	        fn handle(&mut self) -> Vec<Frame> {
648	            let mut replies = Vec::new();
649	            for frame in std::mem::take(&mut self.inbox) {
650	                if frame.kind != FrameKind::Sync {
651	                    continue;
652	                }
653	                match SyncMessage::decode_v1(&frame.payload).unwrap() {
654	                    SyncMessage::SyncStep1(sv) => {
655	                        let update = self.doc.transact().encode_state_as_update_v1(&sv);
656	                        replies.push(sync(SyncMessage::SyncStep2(update)));
657	                    }
658	                    SyncMessage::SyncStep2(u) | SyncMessage::Update(u) => {
659	                        self.doc
660	                            .transact_mut()
661	                            .apply_update(Update::decode_v1(&u).unwrap())
662	                            .unwrap();
663	                    }
664	                }
665	            }
666	            replies
667	        }
668	    }
