674	    fn send(
675	        board: &mut BoardSync<MemoryStore>,
676	        clients: &mut [Client],
677	        from: usize,
678	        frame: Frame,
679	    ) -> Result<(), String> {
680	        let wire = Frame::decode(&frame.encode()).unwrap();
681	        let outgoing = board.receive(&mut clients[from].session, wire)?;
682	        for out in outgoing {
683	            for (i, client) in clients.iter_mut().enumerate() {
684	                if out.route.reaches(i == from, &client.session) {
685	                    client.inbox.push(out.frame.clone());
686	                }
687	            }
688	        }
689	        Ok(())
690	    }
