692	    fn pump(board: &mut BoardSync<MemoryStore>, clients: &mut [Client]) {
693	        loop {
694	            let pending: Vec<(usize, Vec<Frame>)> = clients
695	                .iter_mut()
696	                .enumerate()
697	                .map(|(i, c)| (i, c.handle()))
698	                .collect();
699	            if pending.iter().all(|(_, frames)| frames.is_empty()) {
700	                return;
701	            }
702	            for (i, frames) in pending {
703	                for frame in frames {
704	                    send(board, clients, i, frame).unwrap();
705	                }
706	            }
707	        }
708	    }
