710	    fn connect(board: &mut BoardSync<MemoryStore>, clients: &mut [Client], i: usize) {
711	        send(
712	            board,
713	            clients,
714	            i,
715	            Frame::new(TILE, FrameKind::Subscribe, vec![]),
716	        )
717	        .unwrap();
718	        let sv = clients[i].doc.transact().state_vector();
719	        send(board, clients, i, sync(SyncMessage::SyncStep1(sv))).unwrap();
720	        pump(board, clients);
721	    }
