import type { StoredObject } from "@stallion/client-store";
import {
  type BBox,
  nativeLevel,
  type Point,
  place,
  TILE_SIZE,
  type Tile,
  tileWorldSize,
  toTileLocal,
} from "@stallion/geometry";
import type { PencilSize, Stroke, Point as StrokePoint } from "@stallion/schema";
import getStroke, { type StrokeOptions } from "perfect-freehand";

export const PALETTE = ["#1f2328", "#e5484d", "#f76b15", "#30a46c", "#0090ff", "#8e4ec6"] as const;

export const PENCIL_SIZES: readonly PencilSize[] = ["Small", "Medium", "Large"];

const PENCIL_PX: Record<PencilSize, number> = { Small: 3, Medium: 8, Large: 20 };

export const MAX_POINTS = 4096;

export const strokeWorldWidth = (size: PencilSize, nativeZoom: number): number =>
  PENCIL_PX[size] * 2 ** (nativeZoom - 0.5);

const strokeOptions = (size: number, last: boolean): StrokeOptions => ({
  size,
  thinning: 0.5,
  smoothing: 0.5,
  streamline: 0.4,
  simulatePressure: false,
  last,
});

export const outlinePath = (
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): Path2D => {
  const outline = getStroke([...points], strokeOptions(size, last));
  const path = new Path2D();
  const [first, ...rest] = outline;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  path.closePath();
  return path;
};

export type Draft = {
  colour: number;
  size: PencilSize;
  nativeZoom: number;
  points: StrokePoint[];
};

export const startDraft = (colour: number, size: PencilSize, zoom: number): Draft => ({
  colour,
  size,
  nativeZoom: nativeLevel(zoom),
  points: [],
});

const draftBounds = (draft: Draft): BBox => {
  const margin = strokeWorldWidth(draft.size, draft.nativeZoom);
  const xs = draft.points.map((p) => p[0]);
  const ys = draft.points.map((p) => p[1]);
  return {
    minX: Math.min(...xs) - margin,
    minY: Math.min(...ys) - margin,
    maxX: Math.max(...xs) + margin,
    maxY: Math.max(...ys) + margin,
  };
};

const randomHex = (bytes: number): string =>
  Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");

const newObjectId = (): string => `${Date.now().toString(36).padStart(9, "0")}${randomHex(6)}`;

export const finishDraft = (draft: Draft): StoredObject | undefined => {
  if (draft.points.length === 0) return undefined;
  const bbox = draftBounds(draft);
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const { tile } = placed;
  const stroke: Stroke = {
    type: "Stroke",
    objectId: newObjectId(),
    nativeZoom: draft.nativeZoom,
    bbox,
    colour: draft.colour,
    size: draft.size,
    points: draft.points.map(([x, y, pressure]) => {
      const local = toTileLocal(tile, { x, y });
      return [local.x, local.y, pressure];
    }),
  };
  return { tile, object: stroke };
};

export const localScale = (tile: Tile): number => tileWorldSize(tile.level) / TILE_SIZE;

export const strokeLocalPath = (tile: Tile, stroke: Stroke): Path2D =>
  outlinePath(
    stroke.points,
    strokeWorldWidth(stroke.size, stroke.nativeZoom) / localScale(tile),
    true,
  );

export const draftScreenPath = (
  draft: Draft,
  toScreen: (world: Point) => Point,
  zoom: number,
): Path2D =>
  outlinePath(
    draft.points.map(([x, y, pressure]) => {
      const screen = toScreen({ x, y });
      return [screen.x, screen.y, pressure];
    }),
    strokeWorldWidth(draft.size, draft.nativeZoom) * zoom,
    false,
  );
import { type BBox, contains, fromTileLocal, type Point, type Tile } from "@stallion/geometry";
import type { Stroke } from "@stallion/schema";
import { strokeWorldWidth } from "./stroke";

export const ERASER_TOLERANCE_PX = 8;

const segmentDistance = (p: Point, a: Point, b: Point): number => {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const lengthSquared = dx * dx + dy * dy;
  const t =
    lengthSquared === 0
      ? 0
      : Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / lengthSquared));
  return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
};

const pointBox = ({ x, y }: Point): BBox => ({ minX: x, minY: y, maxX: x, maxY: y });

const grow = (bbox: BBox, margin: number): BBox => ({
  minX: bbox.minX - margin,
  minY: bbox.minY - margin,
  maxX: bbox.maxX + margin,
  maxY: bbox.maxY + margin,
});

export const hitsStroke = (tile: Tile, stroke: Stroke, world: Point, zoom: number): boolean => {
  const reachPx =
    ERASER_TOLERANCE_PX + (strokeWorldWidth(stroke.size, stroke.nativeZoom) * zoom) / 2;
  if (!contains(grow(stroke.bbox, reachPx / zoom), pointBox(world))) return false;
  const screen = stroke.points.map(([x, y]) => {
    const point = fromTileLocal(tile, { x, y });
    return { x: (point.x - world.x) * zoom, y: (point.y - world.y) * zoom };
  });
  const origin = { x: 0, y: 0 };
  const [first] = screen;
  if (!first) return false;
  if (screen.length === 1) return Math.hypot(first.x, first.y) <= reachPx;
  return screen.some((point, index) => {
    const next = screen[index + 1];
    return next !== undefined && segmentDistance(origin, point, next) <= reachPx;
  });
};
import { type BoardStore, openBoardStore, type StoredObject } from "@stallion/client-store";
import type { BoardOptions, BoardStatus, LiveObjects, StallionBoard } from "@stallion/client-sync";
import { type BBox, viewTiles } from "@stallion/geometry";
import { errorMessage } from "./report";

export type Connection = "Connected" | "Reconnecting" | "Offline" | "LocalOnly";

export const CONNECTION_LABEL: Record<Connection, string> = {
  Connected: "Connected",
  Reconnecting: "Reconnecting",
  Offline: "Offline",
  LocalOnly: "Local only: strokes stay in this browser",
};

export const VIEW_DEBOUNCE_MS = 100;

export type Awareness = StallionBoard["awareness"];

export type BoardSource = {
  view(viewport: BBox, zoom: number): void;
  commit(stored: StoredObject): void;
  erase(objectId: string): void;
  readonly objects: LiveObjects;
  readonly awareness: Awareness | undefined;
  close(): Promise<void>;
};

export type OpenBoard = (url: string, boardId: string, options?: BoardOptions) => StallionBoard;

export type SourceOptions = {
  url: string | undefined;
  boardId: string;
  openBoard: OpenBoard;
  onConnection: (connection: Connection) => void;
  onError: (message: string) => void;
};

export const connectionFor = (status: BoardStatus, online: boolean): Connection => {
  if (status === "Open") return "Connected";
  if (!online) return "Offline";
  return status === "Closed" ? "Offline" : "Reconnecting";
};

const liveObjects = (): {
  objects: LiveObjects;
  map: Map<string, StoredObject>;
  notify: (changed: ReadonlySet<string>) => void;
} => {
  const map = new Map<string, StoredObject>();
  const listeners = new Set<(changed: ReadonlySet<string>) => void>();
  const objects: LiveObjects = Object.assign(map, {
    observe(listener: (changed: ReadonlySet<string>) => void): () => void {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  });
  const notify = (changed: ReadonlySet<string>): void => {
    if (changed.size === 0) return;
    for (const listener of listeners) listener(changed);
  };
  return { objects, map, notify };
};

const debounced = (run: (viewport: BBox, zoom: number) => void) => {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return {
    call(viewport: BBox, zoom: number): void {
      clearTimeout(timer);
      timer = setTimeout(() => run(viewport, zoom), VIEW_DEBOUNCE_MS);
    },
    cancel(): void {
      clearTimeout(timer);
    },
  };
};

export function openLocalSource(boardId: string, onError: (message: string) => void): BoardSource {
  const { objects, map, notify } = liveObjects();
  const removed = new Set<string>();
  const storeReady: Promise<BoardStore> = openBoardStore(boardId);
  const fail = (action: string) => (error: unknown) => onError(`${action}: ${errorMessage(error)}`);
  storeReady.catch(fail("Could not open the local board storage"));

  const setView = debounced((viewport, zoom) => {
    const tiles = viewTiles(viewport, zoom);
    storeReady
      .then((store) => store.query([...tiles.live, ...tiles.snapshot]))
      .then((found) => {
        const changed = new Set<string>();
        for (const stored of found) {
          const { objectId } = stored.object;
          if (map.has(objectId) || removed.has(objectId)) continue;
          map.set(objectId, stored);
          changed.add(objectId);
        }
        notify(changed);
      })
      .catch(fail("Could not load the board from local storage"));
  });

  return {
    view: setView.call,
    commit(stored) {
      map.set(stored.object.objectId, stored);
      notify(new Set([stored.object.objectId]));
      storeReady
        .then((store) => store.put(stored))
        .catch(fail("Could not save the stroke to local storage"));
    },
    erase(objectId) {
      const stored = map.get(objectId);
      if (!stored) return;
      removed.add(objectId);
      map.delete(objectId);
      notify(new Set([objectId]));
      storeReady
        .then((store) => store.remove(objectId, stored.tile))
        .catch(fail("Could not delete the stroke from local storage"));
    },
    objects,
    awareness: undefined,
    async close() {
      setView.cancel();
      await storeReady.then(
        (store) => store.close(),
        () => undefined,
      );
    },
  };
}

export function openSyncSource(url: string, options: SourceOptions): BoardSource {
  const online = () => globalThis.navigator?.onLine !== false;
  const board = options.openBoard(url, options.boardId, {
    onStatus: (status) => options.onConnection(connectionFor(status, online())),
    onError: ({ tileKey, reason }) =>
      options.onError(`Sync failed${tileKey ? ` on tile ${tileKey}` : ""}: ${reason}`),
  });
  options.onConnection(connectionFor(board.status, online()));
  const setView = debounced((viewport, zoom) => board.setView(viewport, zoom));
  return {
    view: setView.call,
    commit: (stored) => board.put(stored),
    erase: (objectId) => board.remove(objectId),
    objects: board.objects,
    awareness: board.awareness,
    close() {
      setView.cancel();
      return board.close();
    },
  };
}

export function openSource(options: SourceOptions): BoardSource {
  if (!options.url) {
    options.onConnection("LocalOnly");
    return openLocalSource(options.boardId, options.onError);
  }
  try {
    return openSyncSource(options.url, options);
  } catch (error) {
    options.onError(
      `Could not connect to ${options.url} (${errorMessage(error)}), working local only`,
    );
    options.onConnection("LocalOnly");
    return openLocalSource(options.boardId, options.onError);
  }
}
