};

type PendingRecord = {
  boardId: string;
  level: number;
  tx: number;
  ty: number;
  update: Uint8Array;
};

interface StallionDB extends DBSchema {
  objects: { key: TileKey; value: TileRecord };
  tiles: {
    key: [string, number, number, number];
    value: TileStateRecord;
    indexes: { usedAt: number };

content.content:
