            .step_by(2)
            .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
            .collect();
        let expected = Move {
            object_id: "stroke-0001".into(),
            from_tile: "0:0:0".into(),
            to_tile: "1:-1:2".into(),
            from_update: vec![1],
            to_update: vec![2, 3],
        };
