const touchPath = async (page, points) => {
  const cdp = await page.context().newCDPSession(page);
  const touch = (type, p) =>
    cdp.send("Input.dispatchTouchEvent", {
      type,
      touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [],
    });
  const [first, ...rest] = points;
  await touch("touchStart", first);
  for (const p of rest) await touch("touchMove", p);
  await touch("touchEnd");
  await cdp.detach();
};

const rows = (page) =>
  page.evaluate(
    () =>
      new Promise((resolve, reject) => {
        const req = indexedDB.open("stallion");
        req.onerror = () => reject(req.error);
        req.onsuccess = () => {
          const db = req.result;
          if (![...db.objectStoreNames].includes("objects")) return resolve([]);
          const all = db.transaction("objects").objectStore("objects").getAll();
          all.onsuccess = () => {
            resolve(all.result.map((r) => `${r.level}:${r.tx}:${r.ty}/${r.objectId}`));
            db.close();
          };
        };
      }),
  );

