  page.evaluate(
    ([x, y]) => {
      const c = document.querySelector("canvas.surface");
      const ctx = c.getContext("2d");
      const dpr = window.devicePixelRatio || 1;
      const d = ctx.getImageData(Math.round(x * dpr) - 6, Math.round(y * dpr) - 6, 12, 12).data;
      let ink = 0;
      for (let i = 0; i < d.length; i += 4) if (d[i] + d[i + 1] + d[i + 2] < 300) ink++;
      return ink;
    },
    [x, y],
  );

