  const y = vp.height * 0.5;
  const points = Array.from({ length: 24 }, (_, i) => ({ x: 120 + i * 8, y: y + Math.sin(i / 3) * 20 }));
  await touchPath(page, points);
  await page.waitForTimeout(600);
  const drawnShot = await shot("1-drawn");
  const before = await rows(page);
  await page.getByRole("button", { name: "Select tool" }).click();
  const grab = points[12];
  const dx = vp.width * 0.6;
  const drag = Array.from({ length: 30 }, (_, i) => ({ x: grab.x + (dx * i) / 29, y: grab.y }));
  await touchPath(page, drag);
  await page.waitForTimeout(800);
  const draggedShot = await shot("2-dragged");
  const after = await rows(page);
  const oldInk = await inkAt(page, grab.x, grab.y);
  const newInk = await inkAt(page, grab.x + dx, grab.y);
  await page.reload({ waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible" });
  await page.waitForTimeout(1200);
  const reloadedShot = await shot("3-reloaded");
  const reloaded = await rows(page);
  const oldInkReload = await inkAt(page, grab.x, grab.y);
  const newInkReload = await inkAt(page, grab.x + dx, grab.y);
  report.push({
    scheme,
    before,
    after,
    reloaded,
    ink: { oldInk, newInk, oldInkReload, newInkReload },
    errors,
    shots: [drawnShot, draggedShot, reloadedShot],
  });
  await context.close();
}
await browser.close();
console.log(JSON.stringify(report, null, 2));
